@Singleton
public class EventPipeline
{
	private static final Logger log = LoggerFactory.getLogger(EventPipeline.class);
	private static final long RAID_GROUP_SETTLE_MILLIS = 1_500L;
	private final EventDeduplicator deduplicator = new EventDeduplicator(8_000L);
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
	private final Map<String, CaptureGroup> captureGroups = new ConcurrentHashMap<>();
	private final Set<String> raidGroupsBeingSubmitted = ConcurrentHashMap.newKeySet();
	private final Map<String, ZweetnekkenModels.EventEnvelope> diaryCaptures = new ConcurrentHashMap<>();
	private volatile CaptureGroup recentTriggerGroup;
	@Inject private Client client;
	@Inject private ZweetnekkenConfig config;
	@Inject private ScreenshotService screenshots;
	@Inject private EvidenceStore store;
	@Inject private ZweetnekkenApiClient api;
	@Inject private RulesService rules;
	@Inject private ZweetnekkenDataService data;
	@Inject private PartyTracker parties;
	@Inject private ScheduledExecutorService executor;

	public void addListener(Runnable listener) { listeners.add(listener); }
	public void removeListener(Runnable listener) { listeners.remove(listener); }

	public void capture(String type, String dedupeKey, ZweetnekkenModels.Source source, List<ZweetnekkenModels.Item> items,
		java.util.Map<String, Object> details, boolean includeParty)
	{
		capture(type, dedupeKey, source, items, details, includeParty, null, true, true, null);
	}

	/** Captures an event with the party snapshot taken at the observed completion. */
	public void capture(String type, String dedupeKey, ZweetnekkenModels.Source source, List<ZweetnekkenModels.Item> items,
		java.util.Map<String, Object> details, ZweetnekkenModels.Party party)
	{
		capture(type, dedupeKey, source, items, details, party != null, null, true, true, party);
	}

	public void capture(String type, String dedupeKey, ZweetnekkenModels.Source source, List<ZweetnekkenModels.Item> items,
		java.util.Map<String, Object> details, boolean includeParty, String rulesVersionOverride,
		boolean screenshotRequired, boolean finalizeSubmission)
	{
		capture(type, dedupeKey, source, items, details, includeParty, rulesVersionOverride,
			screenshotRequired, finalizeSubmission, null);
	}

	private void capture(String type, String dedupeKey, ZweetnekkenModels.Source source, List<ZweetnekkenModels.Item> items,
		java.util.Map<String, Object> details, boolean includeParty, String rulesVersionOverride,
		boolean screenshotRequired, boolean finalizeSubmission, ZweetnekkenModels.Party partyOverride)
	{
		if ("loot_test".equalsIgnoreCase(type))
		{
			log.warn("Ignoring legacy test-only loot event; test captures are disabled in this plugin release");
			return;
		}
		// Ordinary and test loot events are both loot submissions. Do not capture or
		// upload either for Trialists; retain unrelated plugin features such as PBs,
		// pets, collection log and achievements. The backend independently enforces this.
		if (isLootSubmissionType(type) && !data.canSubmitLoot())
		{
			log.debug("Skipping loot capture because the current Zweetnekken rank cannot submit loot");
			return;
		}
		Player local = client.getLocalPlayer();
		long now = System.currentTimeMillis();
		if (local == null || local.getName() == null) return;
		String accountHash = String.valueOf(client.getAccountHash());
		String eventKey = "diary".equals(type) ? accountHash + '|' + dedupeKey : dedupeKey;
		if (!deduplicator.accept(type + '|' + eventKey, now)) return;
		ZweetnekkenModels.EventEnvelope envelope = new ZweetnekkenModels.EventEnvelope();
		envelope.eventId = UUID.randomUUID().toString(); envelope.eventType = type; envelope.capturedAt = Instant.now().toString();
		envelope.player = new ZweetnekkenModels.PlayerIdentity(); envelope.player.name = local.getName(); envelope.player.accountHash = accountHash;
		envelope.source = source; if (items != null) envelope.items.addAll(items); if (details != null) envelope.details.putAll(details);
		if (!canSendDiary(envelope) || ("diary".equals(type) && !reserveDiaryTime(envelope))) return;
		CaptureGroup group = groupFor(type, source, details, now);
		boolean coordinatedRaidEvidence = group.coordinatesRaidEvidence(type);
		group.captureStarted(now);
		String partySource = source == null ? null : source.name;
		if (partySource == null && details != null && details.get("record") instanceof ZweetnekkenModels.PbRecord)
			partySource = ((ZweetnekkenModels.PbRecord) details.get("record")).activity;
		boolean individualAward = isIndividualAward(type, partySource, details)
			|| ("loot".equals(type) && source != null && "creation".equals(source.type));
		envelope.party = partyOverride != null ? partyOverride
			: includeParty ? parties.snapshot(partySource, individualAward) : null;
		// Collection-log notifications normally have no party metadata. Keep a
		// provisional raid roster for a clog-only raid; prepareRaidGroup removes it
		// when normal raid loot supplies the authoritative roster.
		if (envelope.party == null && "collection_log".equals(type) && isRaidSource(partySource))
			envelope.party = parties.snapshot(partySource, false);
		if (individualAward && envelope.party == null)
			envelope.party = parties.snapshot(partySource, true);
		envelope.rulesVersion = rulesVersionOverride == null || rulesVersionOverride.isBlank()
			? rules.current().version : rulesVersionOverride;
		envelope.pluginVersion = ZweetnekkenApiClient.PLUGIN_VERSION;
		envelope.context.put("world", client.getWorld()); envelope.context.put("gameCycle", client.getGameCycle());
		envelope.context.put("submissionGroupId", group.id);
		envelope.context.put("submissionTypes", group.types());
		envelope.context.put("finalizeSubmission", finalizeSubmission);
		if (!screenshotRequired)
		{
			executor.execute(() ->
			{
				try
				{
					refreshStoredGroup(group);
					envelope.context.put("submissionTypes", group.types());
					EvidenceStore.Record record = store.saveMetadata(envelope); notifyListeners();
					group.captureFinished();
					if (coordinatedRaidEvidence) queueRaidGroup(group);
					else upload(record, false);
				}
				catch (Exception e)
				{
					group.captureFinished();
					log.error("Could not save evidence metadata for event {} ({})", envelope.eventId, envelope.eventType, e);
				}
				finally { diaryCaptures.remove(envelope.eventId); }
			});
			return;
		}
		screenshots.captureNextFrame(image ->
		{
			if (image == null)
			{
				diaryCaptures.remove(envelope.eventId);
				group.captureFinished();
				log.error("Evidence capture returned no screenshot for event {} ({})", envelope.eventId, envelope.eventType);
				return;
			}
			try
			{
				refreshStoredGroup(group);
				envelope.context.put("submissionTypes", group.types());
				EvidenceStore.Record record = store.save(envelope, image); notifyListeners();
				group.captureFinished();
				if (coordinatedRaidEvidence) queueRaidGroup(group);
				else upload(record, false);
			}
			catch (Exception e)
			{
				group.captureFinished();
				log.error("Could not save evidence for event {} ({})", envelope.eventId, envelope.eventType, e);
			}
			finally { diaryCaptures.remove(envelope.eventId); }
		});
	}

	private synchronized boolean reserveDiaryTime(ZweetnekkenModels.EventEnvelope event)
	{
		Map<?, ?> diary = PvmDiaryTime.diaryDetails(event);
		Object activityId = diary.get("activityId");
		Object value = diary.get("value");
		// Completion and wave-based activities do not use elapsed time.
		if (!(activityId instanceof String) || !(value instanceof Number) || "doom".equals(activityId)
			|| "wave".equals(diary.get("resultKind")))
			return true;

		long millis = ((Number) value).longValue();
		if (millis <= 0 || !PvmDiaryTime.improvesPublishedDiaryTime((String) activityId, millis,
			data.pvmDiaryStatus(event.player.name))) return false;
		for (ZweetnekkenModels.EventEnvelope pending : diaryCaptures.values())
			if (PvmDiaryTime.hasFasterOrEqualDiaryTime(event, pending, activityId, millis)) return false;
		for (EvidenceStore.Record record : store.records())
			if (record.status != ZweetnekkenModels.EventStatus.REJECTED
				&& PvmDiaryTime.hasFasterOrEqualDiaryTime(event, record.metadata, activityId, millis)) return false;

		diaryCaptures.put(event.eventId, event);
		return true;
	}

	public void retryAll()
	{
		executor.execute(() ->
		{
			for (EvidenceStore.Record record : store.records())
				if (record.status == ZweetnekkenModels.EventStatus.PENDING || record.status == ZweetnekkenModels.EventStatus.FAILED)
					upload(record, true);
		});
	}
	public List<EvidenceStore.Record> groupRecords(EvidenceStore.Record record)
	{
		String groupId = submissionGroupId(record);
		if (groupId == null) return record == null ? java.util.Collections.emptyList() : java.util.Collections.singletonList(record);
		List<EvidenceStore.Record> matches = new ArrayList<>();
		for (EvidenceStore.Record candidate : store.records())
			if (groupId.equals(submissionGroupId(candidate))) matches.add(candidate);
		return matches;
	}

	public void retryGroup(EvidenceStore.Record record)
	{
		for (EvidenceStore.Record member : groupRecords(record))
			if (member.status == ZweetnekkenModels.EventStatus.PENDING || member.status == ZweetnekkenModels.EventStatus.FAILED)
				upload(member, true);
	}

	public void updateAndSubmitGroup(EvidenceStore.Record record, int partySize, int clanMembers, int nonClanMembers,
		List<ZweetnekkenModels.PartyMember> partyMembers, String notes)
	{
		for (EvidenceStore.Record member : groupRecords(record))
			if (member.status == ZweetnekkenModels.EventStatus.DRAFT
				|| member.status == ZweetnekkenModels.EventStatus.FAILED)
				updateAndSubmit(member, partySize, clanMembers, nonClanMembers, partyMembers, notes);
	}

	public void upload(EvidenceStore.Record record, boolean manual)
	{
		if (!canSendDiary(record.metadata)) return;
		if (isLegacyTestLootRecord(record))
		{
			log.warn("Skipping legacy test-only loot event {} from the local outbox", eventId(record));
			return;
		}
		String code = config.authenticationCode() == null ? "" : config.authenticationCode().trim();
		if (code.isEmpty())
		{
			log.error("Skipped upload for event {} ({}): no authentication code is configured", eventId(record), eventType(record));
			return;
		}
		record.status = ZweetnekkenModels.EventStatus.UPLOADING; record.error = null; record.updatedAt = Instant.now().toString(); persist(record);
		Filepath screenshot = record.screenshotPath == null || record.screenshotPath.isBlank()
			? null : store.resolveScreenshot(record.screenshotPath);
		if (record.screenshotPath != null && !record.screenshotPath.isBlank() && screenshot == null)
		{
			record.status = ZweetnekkenModels.EventStatus.FAILED;
			record.error = "Lokale bewijsscreenshot is niet beschikbaar";
			record.updatedAt = Instant.now().toString();
			persist(record);
			return;
		}
		executor.execute(() -> api.uploadEvent(record.metadata, screenshot, record.format, result ->
		{
			if (result.isSuccessful() && result.value != null)
			{
				record.submissionId = result.value.submissionId; record.status = parseStatus(result.value.status);
				record.error = validationSummary(result.value.validationMessages);
				record.retryCount = 0;
			}
			else
			{
				record.status = ZweetnekkenModels.EventStatus.FAILED;
				record.error = result.error == null ? "Leeg antwoord van de server" : result.error;
				record.retryCount++;
				log.error("Evidence upload failed for event {} ({}): HTTP {}, error={}, retry={}, manual={}",
					eventId(record), eventType(record), result.statusCode, record.error, record.retryCount, manual);
				if (!manual && result.isRetryable() && record.retryCount <= 5)
				{
					long delay = Math.min(300, 5L << Math.min(6, record.retryCount));
					executor.schedule(() -> upload(record, false), delay, TimeUnit.SECONDS);
				}
			}
			record.updatedAt = Instant.now().toString(); persist(record);
			// Any completed raid upload can unblock another member, including team
			// loot that needs manual review or loot the server already submitted.
			if (isCoordinatedRaidRecord(record)) maybeAutoSubmitRaidGroup(record);
			else if (record.status == ZweetnekkenModels.EventStatus.DRAFT && shouldAutoSubmit(record)) autoSubmit(record);
		}));
	}

	public boolean canSendDiary(ZweetnekkenModels.EventEnvelope event)
	{
		if (event == null || !"diary".equals(event.eventType)) return true;
		Object id = PvmDiaryTime.diaryDetails(event).get("activityId");
		return event.player != null && id instanceof String
			&& data.isPvmDiaryActivityActive(event.player.name, (String) id);
	}

	private static boolean isLegacyTestLootRecord(EvidenceStore.Record record)
	{
		return record != null && record.metadata != null
			&& "loot_test".equalsIgnoreCase(record.metadata.eventType);
	}

	private boolean isCoordinatedRaidRecord(EvidenceStore.Record record)
	{
		if (record == null || record.metadata == null) return false;
		String type = record.metadata.eventType;
		return ("loot".equals(type) || "collection_log".equals(type))
			&& isRaidSource(record.metadata.source == null ? null : record.metadata.source.name);
	}

	private void queueRaidGroup(CaptureGroup group)
	{
		if (group == null) return;
		synchronized (group)
		{
			if (group.uploadTask != null) group.uploadTask.cancel(false);
			group.uploadTask = executor.schedule(() -> uploadRaidGroupWhenReady(group),
				RAID_GROUP_SETTLE_MILLIS, TimeUnit.MILLISECONDS);
		}
	}

	private void uploadRaidGroupWhenReady(CaptureGroup group)
	{
		if (group == null) return;
		synchronized (group)
		{
			if (group.pendingCaptures > 0)
			{
				group.uploadTask = executor.schedule(() -> uploadRaidGroupWhenReady(group),
					RAID_GROUP_SETTLE_MILLIS, TimeUnit.MILLISECONDS);
				return;
			}
			if (group.uploadStarted) return;
			group.uploadStarted = true;
		}

		List<EvidenceStore.Record> records = groupRecords(group.id);
		if (records.isEmpty()) return;
		prepareRaidGroup(records);
		for (EvidenceStore.Record member : records)
			if (member.status == ZweetnekkenModels.EventStatus.PENDING || member.status == ZweetnekkenModels.EventStatus.FAILED)
				upload(member, false);
	}

	private List<EvidenceStore.Record> groupRecords(String groupId)
	{
		List<EvidenceStore.Record> records = new ArrayList<>();
		if (groupId == null) return records;
		for (EvidenceStore.Record record : store.records())
			if (groupId.equals(submissionGroupId(record))) records.add(record);
		return records;
	}

	private void prepareRaidGroup(List<EvidenceStore.Record> records)
	{
		boolean hasLoot = records.stream().anyMatch(record -> record.metadata != null
			&& "loot".equals(record.metadata.eventType));
		for (EvidenceStore.Record record : records)
		{
			if (record.metadata == null || !"collection_log".equals(record.metadata.eventType)
				|| !isRaidSource(record.metadata.source == null ? null : record.metadata.source.name)) continue;
			if (hasLoot)
			{
				// The normal raid-loot envelope is authoritative for the roster.
				record.metadata.party = null;
			}
			else if (record.metadata.party == null)
			{
				record.metadata.party = parties.snapshot(record.metadata.source.name, false);
			}
			try { store.writeRecord(record); }
			catch (Exception e) { log.error("Could not prepare raid evidence group {}", submissionGroupId(record), e); }
		}
	}

	private void maybeAutoSubmitRaidGroup(EvidenceStore.Record trigger)
	{
		String groupId = trigger == null ? null : submissionGroupId(trigger);
		List<EvidenceStore.Record> records = groupRecords(groupId);
		if (records.isEmpty()) return;
		for (EvidenceStore.Record record : records)
			if (record.status != ZweetnekkenModels.EventStatus.DRAFT
				&& record.status != ZweetnekkenModels.EventStatus.SUBMITTED
				&& record.status != ZweetnekkenModels.EventStatus.APPROVED
				&& record.status != ZweetnekkenModels.EventStatus.REJECTED) return;

		ZweetnekkenModels.Party party = null;
		for (EvidenceStore.Record record : records)
			if (record.metadata != null && "loot".equals(record.metadata.eventType) && record.metadata.party != null)
			{
				party = record.metadata.party;
				break;
			}
		if (party == null)
			for (EvidenceStore.Record record : records)
				if (record.metadata != null && record.metadata.party != null)
				{
					party = record.metadata.party;
					break;
				}

		List<EvidenceStore.Record> eligible = new ArrayList<>();
		for (EvidenceStore.Record record : records)
			if (record.status == ZweetnekkenModels.EventStatus.DRAFT && shouldAutoSubmit(record)) eligible.add(record);
		if (eligible.isEmpty() || groupId == null || !raidGroupsBeingSubmitted.add(groupId)) return;
		AtomicInteger remaining = new AtomicInteger(eligible.size());
		Runnable release = () ->
		{
			if (remaining.decrementAndGet() == 0) raidGroupsBeingSubmitted.remove(groupId);
		};
		for (EvidenceStore.Record record : eligible)
			autoSubmit(record, "diary".equals(record.metadata.eventType) ? record.metadata.party : party, release);
	}

	private boolean shouldAutoSubmit(EvidenceStore.Record record)
	{
		if (record == null || record.metadata == null) return false;
		String type = record.metadata.eventType;
		// Loot must remain a draft until the player confirms the participant roster.
		// This mirrors /loot's explicit submit step and prevents a chest drop detected
		// as fixed-solo from reaching Discord before the player can correct the party.
		// All loot submissions require explicit confirmation of the participant roster.
		if ("loot".equals(type) || "loot_test".equals(type)) return false;
		if (!config.autoSubmitEnabled() || record.metadata.context == null) return false;
		if ("personal_best".equals(type) || "diary".equals(type) || "collection_log".equals(type))
			return record.metadata.details != null
				&& Boolean.TRUE.equals(record.metadata.details.get("autoSubmit"));
		Object finalizeSubmission = record.metadata.context.get("finalizeSubmission");
		return Boolean.TRUE.equals(finalizeSubmission)
			|| "true".equalsIgnoreCase(String.valueOf(finalizeSubmission));
	}

	private static boolean isLootSubmissionType(String type)
	{
		return "loot".equalsIgnoreCase(type) || "loot_test".equalsIgnoreCase(type);
	}

	private static boolean isIndividualAward(String type, String sourceName, Map<String, Object> details)
	{
		// Every pet is awarded to the individual player, regardless of activity.
		if ("pet".equals(type) || ("bingo".equals(type) && value(details, "petName") != null))
			return true;
		if (!("loot".equals(type) || "bingo".equals(type)) || details == null) return false;
		return PartyTracker.isIndividualRaidReward(sourceName, value(details, "itemName"));
	}

	private static String value(Map<String, Object> details, String key)
	{
		Object value = details == null ? null : details.get(key);
		return value == null ? null : String.valueOf(value);
	}

	private void autoSubmit(EvidenceStore.Record record)
	{
		ZweetnekkenModels.Party party = record.metadata.party;
		autoSubmit(record, party);
	}

	private void autoSubmit(EvidenceStore.Record record, ZweetnekkenModels.Party party)
	{
		autoSubmit(record, party, () -> { });
	}

	private void autoSubmit(EvidenceStore.Record record, ZweetnekkenModels.Party party, Runnable completion)
	{
		int partySize = party == null ? 1 : party.submittedPartySize;
		int clanMembers = party == null ? 0 : party.submittedClanMemberCount;
		int nonClanMembers = party == null ? 0 : party.submittedNonClanMemberCount;
		updateAndSubmit(record, partySize, clanMembers, nonClanMembers,
			party == null ? List.of() : party.submittedMembers, "", completion);
	}

	public void updateAndSubmit(EvidenceStore.Record record, int partySize, int clanMembers, int nonClanMembers,
		List<ZweetnekkenModels.PartyMember> partyMembers, String notes)
	{
		updateAndSubmit(record, partySize, clanMembers, nonClanMembers, partyMembers, notes, () -> { });
	}

	private void updateAndSubmit(EvidenceStore.Record record, int partySize, int clanMembers, int nonClanMembers,
		List<ZweetnekkenModels.PartyMember> partyMembers, String notes, Runnable completion)
	{
		if (record == null || !canSendDiary(record.metadata))
		{
			completion.run();
			return;
		}
		if (isLegacyTestLootRecord(record))
		{
			log.warn("Skipping submission of legacy test-only loot event {}", eventId(record));
			completion.run();
			return;
		}
		// Keep the permission check in the submission pipeline as well as the UI and
		// backend, so a stale panel or a future caller cannot submit ordinary loot as a Trialist.
		if (record != null && record.metadata != null
			&& isLootSubmissionType(record.metadata.eventType) && !data.canSubmitLoot())
		{
			record.status = ZweetnekkenModels.EventStatus.DRAFT;
			record.error = "Lootdrops submitten is pas beschikbaar vanaf de rang Zweetnek.";
			persist(record);
			completion.run();
			return;
		}
		if (record.submissionId == null)
		{
			record.error = "Inzendings-ID ontbreekt; probeer de upload opnieuw";
			log.error("Could not submit event {}: submission ID is unavailable", eventId(record));
			persist(record);
			completion.run();
			return;
		}
		record.status = ZweetnekkenModels.EventStatus.UPLOADING;
		record.error = null;
		persist(record);
		int size = Math.max(1, partySize);
		int clan = Math.max(0, Math.min(size, clanMembers));
		int nonClan = Math.max(0, Math.min(size - clan, nonClanMembers));
		List<ZweetnekkenModels.PartyMember> members = copyPartyMembers(partyMembers);
		if (record.metadata.party != null)
		{
			record.metadata.party.submittedPartySize = size;
			record.metadata.party.submittedClanMemberCount = clan;
			record.metadata.party.submittedNonClanMemberCount = nonClan;
			record.metadata.party.submittedMembers = members;
		}
		api.updateSubmission(record.submissionId, size, clan, nonClan, members, notes == null ? "" : notes, patched ->
		{
			if (!patched.isSuccessful())
			{
				record.status = ZweetnekkenModels.EventStatus.DRAFT;
				record.error = patched.error;
				log.error("Submission update failed for event {} (submission {}): HTTP {}, error={}",
					eventId(record), record.submissionId, patched.statusCode, patched.error);
				persist(record);
				completion.run();
				return;
			}
			if (!canSendDiary(record.metadata))
			{
				record.status = ZweetnekkenModels.EventStatus.DRAFT;
				persist(record);
				completion.run();
				return;
			}
			api.submit(record.submissionId, submitted ->
			{
				if (submitted.isSuccessful()) { record.status = ZweetnekkenModels.EventStatus.SUBMITTED; record.error = null; }
				else
				{
					record.status = ZweetnekkenModels.EventStatus.DRAFT;
					record.error = submitted.error;
					log.error("Submission failed for event {} (submission {}): HTTP {}, error={}",
						eventId(record), record.submissionId, submitted.statusCode, submitted.error);
				}
				persist(record);
				completion.run();
			});
		});
	}

	public void refreshStatuses(String playerName)
	{
		if (playerName == null || playerName.isBlank()) return;
		api.getSubmissions(playerName, result ->
		{
			if (!result.isSuccessful() || result.value == null)
			{
				log.error("Could not refresh submissions: HTTP {}, error={}", result.statusCode,
					result.error == null ? "empty server response" : result.error);
				return;
			}
			List<EvidenceStore.Record> records = store.records();
			for (ZweetnekkenModels.SubmissionSummary summary : result.value)
			{
				for (EvidenceStore.Record record : records)
				{
					if ((summary.eventId != null && summary.eventId.equals(record.metadata.eventId))
						|| (summary.submissionId != null && summary.submissionId.equals(record.submissionId)))
					{
						record.submissionId = summary.submissionId;
						record.status = parseStatus(summary.status);
						if (summary.error != null && !summary.error.isBlank())
							record.error = summary.error;
						else if (record.status != ZweetnekkenModels.EventStatus.FAILED)
							record.error = null;
						persist(record);
					}
				}
			}
		});
	}

	private void persist(EvidenceStore.Record record)
	{
		try { store.writeRecord(record); }
		catch (Exception e) { log.error("Could not persist event {} ({})", eventId(record), eventType(record), e); }
		notifyListeners();
	}
	private void notifyListeners() { for (Runnable listener : listeners) listener.run(); }

	private synchronized CaptureGroup groupFor(String type, ZweetnekkenModels.Source source,
		java.util.Map<String, Object> details, long now)
	{
		String key = encounterKey(source, details);
		CaptureGroup group = key == null ? null : captureGroups.get(key);
		if (group == null || now - group.lastSeen > 8_000L || group.contains(type))
		{
			CaptureGroup recent = recentTriggerGroup;
			boolean triggerPair = recent != null && now - recent.lastSeen <= 4_000L
				&& (("bingo".equals(type) && recent.contains("personal_best"))
					|| ("personal_best".equals(type) && recent.contains("bingo")));
			group = triggerPair ? recent : new CaptureGroup(UUID.randomUUID().toString(), now,
				isRaidSource(source == null ? null : source.name));
			if (key != null) captureGroups.put(key, group);
		}
		group.add(type, now);
		if ("bingo".equals(type) || "personal_best".equals(type) || group.contains("bingo")) recentTriggerGroup = group;
		return group;
	}

	private void refreshStoredGroup(CaptureGroup group)
	{
		for (EvidenceStore.Record record : store.records())
		{
			if (!group.id.equals(submissionGroupId(record)) || record.metadata == null) continue;
			record.metadata.context.put("submissionTypes", group.types());
			try { store.writeRecord(record); }
			catch (Exception e) { log.error("Could not update submission group {}", group.id, e); }
		}
	}

	private static String encounterKey(ZweetnekkenModels.Source source, java.util.Map<String, Object> details)
	{
		String value = source == null ? null : source.name;
		if ((value == null || value.isBlank()) && details != null)
		{
			Object record = details.get("record");
			if (record instanceof ZweetnekkenModels.PbRecord) value = ((ZweetnekkenModels.PbRecord) record).activity;
			else if (record instanceof java.util.Map) value = String.valueOf(((java.util.Map<?, ?>) record).get("activity"));
		}
		if (value == null || value.isBlank() || "null".equals(value)) return null;
		String normalized = value.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "");
		// Loot and collection-log sources can use different raid variants (for
		// example, normal versus hard mode). They still belong to one evidence
		// group for this completion.
		if (isRaidSource(value))
		{
			if (normalized.startsWith("chambersofxeric")) return "chambersofxeric";
			if (normalized.startsWith("theatreofblood")) return "theatreofblood";
			if (normalized.startsWith("tombsofamascut")) return "tombsofamascut";
			if (normalized.equals("thefracturedarchive") || normalized.equals("fracturedarchive")) return "fracturedarchive";
		}
		return normalized;
	}

	private static List<ZweetnekkenModels.PartyMember> copyPartyMembers(List<ZweetnekkenModels.PartyMember> source)
	{
		List<ZweetnekkenModels.PartyMember> copy = new ArrayList<>();
		if (source == null) return copy;
		for (ZweetnekkenModels.PartyMember member : source)
		{
			if (member == null) continue;
			ZweetnekkenModels.PartyMember value = new ZweetnekkenModels.PartyMember();
			value.name = member.name == null ? "" : member.name.trim();
			value.clanMember = member.clanMember;
			copy.add(value);
		}
		return copy;
	}

	private static boolean isRaidSource(String source)
	{
		return source != null && BossRegistry.isRaid(source);
	}

	public static String submissionGroupId(EvidenceStore.Record record)
	{
		if (record == null || record.metadata == null || record.metadata.context == null) return null;
		Object value = record.metadata.context.get("submissionGroupId");
		return value == null ? null : String.valueOf(value);
	}

	private static final class CaptureGroup
	{
		private final String id;
		private final boolean raid;
		private final Set<String> eventTypes = new LinkedHashSet<>();
		private long lastSeen;
		private int pendingCaptures;
		private boolean uploadStarted;
		private ScheduledFuture<?> uploadTask;
		private CaptureGroup(String id, long lastSeen, boolean raid)
		{
			this.id = id;
			this.lastSeen = lastSeen;
			this.raid = raid;
		}
		private synchronized void add(String type, long seen) { eventTypes.add(type); lastSeen = seen; }
		private synchronized boolean contains(String type) { return eventTypes.contains(type); }
		private synchronized List<String> types() { return new ArrayList<>(eventTypes); }
		private synchronized boolean coordinatesRaidEvidence(String type)
		{
			return raid && ("loot".equals(type) || "collection_log".equals(type));
		}
		private synchronized void captureStarted(long started) { pendingCaptures++; lastSeen = started; }
		private synchronized void captureFinished() { pendingCaptures = Math.max(0, pendingCaptures - 1); }
	}

	private static String eventId(EvidenceStore.Record record) { return record == null || record.metadata == null ? "unknown" : record.metadata.eventId; }
	private static String eventType(EvidenceStore.Record record) { return record == null || record.metadata == null ? "unknown" : record.metadata.eventType; }
	private static String validationSummary(List<ZweetnekkenModels.ValidationMessage> messages)
	{
		if (messages == null || messages.isEmpty()) return null;
		return messages.stream().filter(java.util.Objects::nonNull)
			.map(message -> (message.field == null || message.field.isBlank() ? "" : message.field + ": ")
				+ (message.message == null ? "Validation failed" : message.message))
			.collect(java.util.stream.Collectors.joining(" "));
	}
	private static ZweetnekkenModels.EventStatus parseStatus(String status)
	{
		if (status == null) return ZweetnekkenModels.EventStatus.DRAFT;
		try { return ZweetnekkenModels.EventStatus.valueOf(status.toUpperCase(java.util.Locale.ROOT)); }
		catch (IllegalArgumentException e) { return ZweetnekkenModels.EventStatus.DRAFT; }
	}
}

package com.zweetnekken.evidence;

import com.google.gson.Gson;
import com.zweetnekken.model.ZweetnekkenModels;
import com.zweetnekken.service.ImageCache;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;

@Singleton
public class EvidenceStore
{
	private final Filepath root;
	private final Gson gson;

	@Inject
	public EvidenceStore(Gson gson, Filepath pluginDirectory)
	{
		this.gson = gson;
		this.root = pluginDirectory;
	}

	public Record save(ZweetnekkenModels.EventEnvelope envelope, BufferedImage image) throws IOException
	{
		ScreenshotEncoder.Encoded encoded = ScreenshotEncoder.encode(image);
		LocalDate date = LocalDate.now();
		String player = ImageCache.safeName(envelope.player.name);
		Filepath dir = root.join("evidence", player, date.toString());
		dir.createDirectories();
		Filepath imagePath = dir.joinSegment(envelope.eventId + "." + encoded.format);
		imagePath.write(encoded.bytes);

		Record record = new Record();
		record.metadata = envelope;
		record.screenshotPath = "evidence/" + player + "/" + date + "/" + imagePath.getFileName();
		record.format = encoded.format;
		record.status = ZweetnekkenModels.EventStatus.PENDING;
		record.updatedAt = Instant.now().toString();
		writeRecord(record);
		return record;
	}

	public synchronized Record saveMetadata(ZweetnekkenModels.EventEnvelope envelope) throws IOException
	{
		Record record = new Record();
		record.metadata = envelope;
		record.status = ZweetnekkenModels.EventStatus.PENDING;
		record.updatedAt = Instant.now().toString();
		writeRecord(record);
		return record;
	}

	public synchronized void writeRecord(Record record) throws IOException
	{
		Filepath outbox = root.joinSegment("outbox");
		outbox.createDirectories();
		String name = record.metadata.eventId + ".json";
		Filepath target = outbox.joinSegment(name);
		Filepath temp = outbox.joinSegment(name + ".tmp");
		temp.write(gson.toJson(record));
		temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
	}

	public synchronized List<Record> records()
	{
		Filepath outbox = root.joinSegment("outbox");
		if (!outbox.isDirectory()) return new ArrayList<>();
		try (Stream<Filepath> paths = outbox.walk(1))
		{
			return paths.filter(path -> path.isFile() && path.getFileName().endsWith(".json"))
				.map(this::read)
				.filter(java.util.Objects::nonNull)
				.sorted(Comparator.comparing((Record r) ->
					r.metadata == null || r.metadata.capturedAt == null ? "" : r.metadata.capturedAt).reversed())
				.collect(Collectors.toList());
		}
		catch (IOException e)
		{
			return new ArrayList<>();
		}
	}

	private Record read(Filepath path)
	{
		try (Reader reader = path.openReader())
		{
			Record record = gson.fromJson(reader, Record.class);
			if (record != null && record.screenshotPath != null)
				record.screenshotPath = relativeScreenshotPath(record.screenshotPath);
			return record;
		}
		catch (IOException | RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Resolve a persisted screenshot path inside this plugin's data directory.
	 * Old records stored absolute paths under .runelite/zweetnekken; normalize
	 * those paths after RuneLite migrates the legacy directory to plugin-data.
	 */
	public Filepath resolveScreenshot(String storedPath)
	{
		if (storedPath == null || storedPath.isBlank()) return null;
		String relative = relativeScreenshotPath(storedPath);
		if (isAbsolutePath(relative)) return null;
		try
		{
			Filepath path = root.join(relative);
			return path.isFile() ? path : null;
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static String relativeScreenshotPath(String storedPath)
	{
		if (storedPath == null) return null;
		String normalized = storedPath.replace('\\', '/');
		if (!isAbsolutePath(normalized)) return normalized;

		String marker = "/plugin-data/zweetnekken/";
		int index = normalized.lastIndexOf(marker);
		if (index >= 0) return normalized.substring(index + marker.length());

		marker = "/zweetnekken/";
		index = normalized.lastIndexOf(marker);
		if (index >= 0) return normalized.substring(index + marker.length());
		return normalized;
	}

	private static boolean isAbsolutePath(String value)
	{
		return value != null && (value.startsWith("/") || value.matches("^[A-Za-z]:/.*"));
	}

	public synchronized void deleteLocal(String eventId)
	{
		Filepath recordFile;
		try
		{
			recordFile = root.join("outbox", eventId + ".json");
		}
		catch (IllegalArgumentException e)
		{
			return;
		}
		Record record = read(recordFile);
		try
		{
			if (record != null && record.screenshotPath != null)
			{
				Filepath screenshot = resolveScreenshot(record.screenshotPath);
				if (screenshot != null) screenshot.deleteIfExists();
			}
			recordFile.deleteIfExists();
		}
		catch (IOException ignored) { }
	}

	public synchronized void pruneUploaded(int retentionDays)
	{
		long cutoff = System.currentTimeMillis() - Math.max(0, retentionDays) * 86_400_000L;
		for (Record record : records())
		{
			if ((record.status == ZweetnekkenModels.EventStatus.DRAFT || record.status == ZweetnekkenModels.EventStatus.SUBMITTED || record.status == ZweetnekkenModels.EventStatus.APPROVED)
				&& parseTime(record.updatedAt) < cutoff) deleteLocal(record.metadata.eventId);
		}
	}

	private static long parseTime(String value) { try { return Instant.parse(value).toEpochMilli(); } catch (RuntimeException e) { return Long.MAX_VALUE; } }

	public static final class Record
	{
		public ZweetnekkenModels.EventEnvelope metadata;
		public String screenshotPath;
		public String format;
		public ZweetnekkenModels.EventStatus status;
		public String submissionId;
		public String error;
		public int retryCount;
		public String updatedAt;
	}
}

package com.zweetnekken.evidence;

import com.zweetnekken.model.ZweetnekkenModels;
import java.util.Map;

final class PvmDiaryTime
{
	private PvmDiaryTime() {}

	static boolean improvesPublishedDiaryTime(String activityId, long millis, ZweetnekkenModels.PvmDiaryStatus status)
	{
		if (status != null && status.activities != null)
		{
			for (ZweetnekkenModels.PvmDiaryActivity activity : status.activities)
				if (activity != null && activityId.equals(activity.id) && activity.bestResult != null
					&& activity.bestResult.value != null && activity.bestResult.value > 0
					&& millis >= activity.bestResult.value) return false;
		}
		return true;
	}

	static boolean hasFasterOrEqualDiaryTime(ZweetnekkenModels.EventEnvelope event,
		ZweetnekkenModels.EventEnvelope previous, Object activityId, long millis)
	{
		if (previous == null || previous.player == null || !"diary".equals(previous.eventType)
			|| !event.player.accountHash.equals(previous.player.accountHash)) return false;
		Map<?, ?> diary = diaryDetails(previous);
		Object value = diary.get("value");
		return activityId.equals(diary.get("activityId")) && value instanceof Number
			&& ((Number) value).longValue() > 0 && ((Number) value).longValue() <= millis;
	}

	static Map<?, ?> diaryDetails(ZweetnekkenModels.EventEnvelope event)
	{
		Object diary = event.details == null ? null : event.details.get("pvmDiary");
		return diary instanceof Map ? (Map<?, ?>) diary : Map.of();
	}
}

/*
 * Portions adapted from the Llama Club screenshot encoder and Dink.
 * See LICENSES/llama-LICENSE.txt and LICENSES/dink-LICENSE.txt.
 */
package com.zweetnekken.evidence;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;

public final class ScreenshotEncoder
{
	private static final int TARGET_BYTES = 2_000_000;
	private ScreenshotEncoder() {}

	public static Encoded encode(BufferedImage image) throws IOException
	{
		ByteArrayOutputStream png = new ByteArrayOutputStream();
		if (!ImageIO.write(image, "png", png)) throw new IOException("PNG writer unavailable");
		if (png.size() <= TARGET_BYTES) return new Encoded("png", png.toByteArray());
		double[] scales = {1.0, .85, .7, .55};
		float[] qualities = {.9f, .86f, .82f, .78f};
		byte[] last = null;
		for (int i = 0; i < scales.length; i++)
		{
			last = jpeg(scale(image, scales[i]), qualities[i]);
			if (last.length <= TARGET_BYTES) break;
		}
		return new Encoded("jpg", last);
	}

	private static BufferedImage scale(BufferedImage input, double scale)
	{
		int width = scale >= 1 ? input.getWidth() : Math.max(1, (int) (input.getWidth() * scale));
		int height = scale >= 1 ? input.getHeight() : Math.max(1, (int) (input.getHeight() * scale));
		// The standard JPEG writer rejects images with an alpha channel (including RuneLite's
		// TYPE_INT_ARGB screenshots) with "Bogus input colorspace". Always render into RGB,
		// even when no resize is needed, before handing the image to that writer.
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = out.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(input, 0, 0, out.getWidth(), out.getHeight(), null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	private static byte[] jpeg(BufferedImage image, float quality) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		ImageWriteParam param = writer.getDefaultWriteParam(); param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT); param.setCompressionQuality(quality);
		try (ImageOutputStream stream = ImageIO.createImageOutputStream(out)) { writer.setOutput(stream); writer.write(null, new IIOImage(image, null, null), param); }
		finally { writer.dispose(); }
		return out.toByteArray();
	}

	public static final class Encoded
	{
		public final String format; public final byte[] bytes;
		Encoded(String format, byte[] bytes) { this.format = format; this.bytes = bytes; }
	}
}

package com.zweetnekken.evidence;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/** Paints evidence labels on a private copy, never on RuneLite's shared frame. */
final class ScreenshotOverlay
{
	private ScreenshotOverlay() { }

	static BufferedImage render(BufferedImage source, String[] lines, Color color)
	{
		BufferedImage result = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = result.createGraphics();
		try
		{
			graphics.drawImage(source, 0, 0, null);
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			FontMetrics metrics = graphics.getFontMetrics();
			int width = 0;
			for (String line : lines) width = Math.max(width, metrics.stringWidth(line));
			int height = lines.length * metrics.getHeight() + 16;
			int x = 8;
			int y = Math.max(0, result.getHeight() - height - 8);
			graphics.setColor(new Color(20, 20, 20, 235));
			graphics.fillRoundRect(x, y, width + 20, height, 8, 8);
			for (int i = 0; i < lines.length; i++)
			{
				// Identity stays legible regardless of the optional Bingo text color.
				graphics.setColor(i == 0 ? Color.WHITE : color);
				graphics.drawString(lines[i], x + 10, y + 8 + metrics.getAscent() + i * metrics.getHeight());
			}
		}
		finally { graphics.dispose(); }
		return result;
	}
}

