	static JScrollPane scroll(JPanel panel, boolean reserveScrollbarSpace) {
		ViewportWidthPanel viewport = new ViewportWidthPanel();
		viewport.setBorder(BorderFactory.createEmptyBorder(0, 6, 8, 6));
		viewport.add(panel, BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(viewport);
		scroll.setBorder(null);
		scroll.setBackground(PANEL_BACKGROUND);
		scroll.getViewport().setBackground(PANEL_BACKGROUND);
		scroll.getViewport().setOpaque(true);
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		// Keep the sidebar width stable when the settings actions expand or collapse.
		scroll.setVerticalScrollBarPolicy(reserveScrollbarSpace
				? JScrollPane.VERTICAL_SCROLLBAR_ALWAYS : JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
		javax.swing.JScrollBar verticalBar = scroll.getVerticalScrollBar();
		verticalBar.setUI(new javax.swing.plaf.basic.BasicScrollBarUI()
		{
			private JButton arrowButton(int direction)
			{
				JButton button = new javax.swing.plaf.basic.BasicArrowButton(direction,
					PANEL_BACKGROUND, PANEL_BACKGROUND, new Color(68, 72, 75), new Color(82, 87, 90));
				button.setBackground(PANEL_BACKGROUND);
				button.setForeground(new Color(150, 150, 140));
				button.setBorder(BorderFactory.createEmptyBorder());
				button.setFocusable(false);
				return button;
			}

			@Override
			protected JButton createDecreaseButton(int orientation)
			{
				return arrowButton(orientation);
			}

			@Override
			protected JButton createIncreaseButton(int orientation)
			{
				return arrowButton(orientation);
			}

			@Override
			protected void configureScrollBarColors()
			{
				thumbColor = new Color(68, 72, 75);
				thumbHighlightColor = new Color(82, 87, 90);
				thumbDarkShadowColor = new Color(48, 52, 54);
				trackColor = PANEL_BACKGROUND;
				trackHighlightColor = CARD_BACKGROUND;
			}
		});
		verticalBar.setBackground(PANEL_BACKGROUND);
		verticalBar.setUnitIncrement(16);
		verticalBar.setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	private static final class ViewportWidthPanel extends JPanel implements Scrollable {
		private ViewportWidthPanel() {
			super(new BorderLayout());
			setBackground(PANEL_BACKGROUND);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize() {
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction) {
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction) {
			return Math.max(16, visible.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth() {
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight() {
			// Preserve the cards' natural height instead of switching between fitting and scrolling.
			return false;
		}
	}

