				g2.fillRoundRect(0, 0, barWidth, getHeight(), 6, 6);
				g2.dispose();
			}
		};
		p.setOpaque(false);
		p.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
