	static JPanel activityCard(ZweetnekkenModels.PvmDiaryActivity activity)
	{
		JPanel row = card();
		row.add(text(safe(activity.name), true, ZweetnekkenTheme.TEXT));
		row.add(Box.createVerticalStrut(5));
		String label = recordLabel(activity.kind);
		if (label != null)
			row.add(pair(label, recordValue(activity), GREEN));
		row.add(pair("Punten behaald", number(activity.earnedPoints), ZweetnekkenTheme.BLUE));
		if (activity.tiers != null)
			for (ZweetnekkenModels.PvmDiaryTier tier : activity.tiers)
			{
				row.add(Box.createVerticalStrut(5));
				row.add(tierRow(tier));
			}
		return row;
	}

	private void renderActivity(ZweetnekkenModels.PvmDiaryStatus status, String activityId)
	{
		ZweetnekkenModels.PvmDiaryActivity selected = null;
		for (ZweetnekkenModels.PvmDiaryActivity activity : status.activities == null
			? java.util.Collections.<ZweetnekkenModels.PvmDiaryActivity>emptyList() : status.activities)
			if (activity != null && activityId.equals(activity.id)) { selected = activity; break; }
		if (selected == null)
		{
			selectedActivity = null;
			refresh();
			return;
		}
		addBackButton("‹  " + safe(selected.category), () -> { selectedActivity = null; refresh(); });
		content.add(Box.createVerticalStrut(8));
		content.add(heading(safe(selected.name).toUpperCase(Locale.ROOT)));
		content.add(Box.createVerticalStrut(8));
		JPanel summary = card();
		summary.add(pair("Teamgrootte", selected.teamSize > 0 ? String.valueOf(selected.teamSize) : "—", Color.WHITE));
		summary.add(pair("Punten", number(selected.earnedPoints), GOLD));
		String recordLabel = recordLabel(selected.kind);
		if (recordLabel != null)
			summary.add(pair(recordLabel, recordValue(selected), GREEN));
		if (selected.nextTarget != null && selected.nextTarget.targetLabel != null)
			summary.add(pair("Volgende doel", selected.nextTarget.targetLabel, Color.WHITE));
		content.add(summary);
		content.add(Box.createVerticalStrut(8));
		content.add(text("TIERS", true, GOLD));
		content.add(Box.createVerticalStrut(5));
		for (ZweetnekkenModels.PvmDiaryTier tier : selected.tiers == null
			? java.util.Collections.<ZweetnekkenModels.PvmDiaryTier>emptyList() : selected.tiers)
		{
			content.add(tierRow(tier));
			content.add(ZweetnekkenPanel.blackDivider(4));
		}
	}

	private static JPanel tierRow(ZweetnekkenModels.PvmDiaryTier tier)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(true);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBackground(tier.completed ? new Color(31, 52, 35) : ZweetnekkenTheme.BACKGROUND);
		row.setBorder(BorderFactory.createEmptyBorder(8, 9, 8, 9));
		JPanel left = new JPanel();
		left.setOpaque(false);
		left.setLayout(new BoxLayout(left, BoxLayout.Y_AXIS));
		left.add(text(safe(tier.tier), true, tier.completed ? GREEN : GOLD));
		left.add(text(localizedTarget(tier.targetLabel), false, MUTED));
		row.add(left, BorderLayout.CENTER);
		JPanel reward = new JPanel();
		reward.setOpaque(false);
		reward.setLayout(new BoxLayout(reward, BoxLayout.Y_AXIS));
		if (tier.completed) reward.add(text("VOLTOOID", true, GREEN));
		reward.add(text("+" + number(tier.points) + " punten", true, tier.completed ? GREEN : GOLD));
		row.add(reward, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private static String localizedTarget(String value)
	{
		if (value == null || value.isBlank() || "completion".equalsIgnoreCase(value)) return "Completion";
		return value;
	}

	private void addBackButton(String label, Runnable action)
	{
		JButton back = actionButton(label, false);
		back.addActionListener(e -> action.run());
		content.add(back);
	}

	private static JPanel cardWithMessage(String message)
	{
		JPanel card = card();
		card.add(text(message, false, MUTED));
		return card;
	}

	private static JPanel card()
	{
		return ZweetnekkenPanel.card();
	}

	private static void makeClickable(JPanel panel, Runnable action)
	{
		panel.setFocusable(true);
		panel.getInputMap(JComponent.WHEN_FOCUSED).put(KeyStroke.getKeyStroke("ENTER"), "openDiaryCategory");
		panel.getInputMap(JComponent.WHEN_FOCUSED).put(KeyStroke.getKeyStroke("SPACE"), "openDiaryCategory");
		panel.getActionMap().put("openDiaryCategory", new AbstractAction()
		{
			@Override public void actionPerformed(java.awt.event.ActionEvent event) { action.run(); }
		});
		addMouseClick(panel, action);
	}

	private static void addMouseClick(Component component, Runnable action)
	{
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		component.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseClicked(MouseEvent event)
			{
				if (event.getButton() == MouseEvent.BUTTON1) action.run();
			}
		});
		if (component instanceof Container)
			for (Component child : ((Container) component).getComponents()) addMouseClick(child, action);
	}

	private static JPanel heading(String value)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel label = text(value, true, GOLD);
		label.setFont(ZweetnekkenTheme.font(true));
		row.add(label, BorderLayout.WEST);
		return row;
	}

	static String recordLabel(String kind)
	{
		if ("time".equals(kind)) return "Beste tijd";
		if ("wave".equals(kind)) return "Hoogste wave";
		return null;
	}

	static String recordValue(ZweetnekkenModels.PvmDiaryActivity activity)
	{
		return activity.bestResult == null || activity.bestResult.label == null
			? "Nog geen record" : activity.bestResult.label;
	}

	static JPanel pair(String name, String value, Color valueColor)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.add(text(name, false, MUTED), BorderLayout.CENTER);
		JLabel valueLabel = text(value, false, valueColor);
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(valueLabel, BorderLayout.EAST);
		int height = row.getPreferredSize().height;
		row.setMinimumSize(new Dimension(0, height));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return row;
	}

	private static JLabel text(String value, boolean bold, Color color)
	{
		JLabel label = new JLabel(value == null ? "—" : value);
		label.setToolTipText(value);
		label.setForeground(color);
		label.setFont(ZweetnekkenTheme.font(bold));
		label.setHorizontalAlignment(SwingConstants.LEFT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setMaximumSize(new Dimension(Integer.MAX_VALUE, label.getPreferredSize().height));
		return label;
	}

	private static JButton actionButton(String title, boolean primary)
	{
		JButton button = ZweetnekkenPanel.actionButton(title, primary);
		button.setHorizontalAlignment(SwingConstants.LEFT);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		button.setPreferredSize(new Dimension(0, 28));
		return button;
	}

	static JProgressBar progress(long current, long total, Color color)
	{
		JProgressBar progress = new JProgressBar(0, 1000);
		progress.setValue(total <= 0 ? 0 : (int) Math.min(1000, Math.max(0, Math.round(1000d * current / total))));
		progress.setAlignmentX(Component.LEFT_ALIGNMENT);
		progress.setStringPainted(false);
		progress.setBorderPainted(false);
		progress.setBackground(new Color(52, 55, 58));
		progress.setForeground(color);
		progress.setPreferredSize(new Dimension(100, 8));
		progress.setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
		return progress;
	}

	private static String number(long number)
	{
		return java.text.NumberFormat.getIntegerInstance(Locale.US).format(number);
	}

	private static String safe(String value) { return value == null || value.isBlank() ? "Onbekend" : value; }
}

package com.zweetnekken.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.LayoutManager;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/** Shared colors, typography, and panel styling for Zweetnekken. */
final class ZweetnekkenTheme
{
	static final Color BACKGROUND = new Color(15, 17, 17);
	static final Color SURFACE = new Color(28, 31, 33);
	static final Color BORDER = new Color(50, 54, 58);
	static final Color TEXT = new Color(230, 230, 220);
	static final Color MUTED = new Color(150, 150, 140);
	static final Color GOLD = new Color(218, 165, 32);
	static final Color BLUE = new Color(66, 165, 245);
	static final Color GREEN = new Color(139, 195, 74);
	static final Color HOVER = new Color(35, 38, 42);

	private ZweetnekkenTheme() { }

	static Font font(boolean bold)
	{
		return bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont();
	}

	static void typography(Component component)
	{
		Font current = component.getFont();
		if (current != null
				&& !current.getName().equals(FontManager.getRunescapeBoldFont().getName())
				&& !current.getName().equals(FontManager.getRunescapeSmallFont().getName()))
		{
			component.setFont(font(current.isBold()));
		}
		if (component instanceof Container)
			for (Component child : ((Container) component).getComponents()) typography(child);
	}

	static JPanel surface()
	{
		JPanel panel = surface(new java.awt.FlowLayout());
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		return panel;
	}

	static JPanel surface(LayoutManager layout)
	{
		JPanel panel = new JPanel(layout)
		{
			@Override protected void paintComponent(java.awt.Graphics graphics)
			{
				java.awt.Graphics2D g = (java.awt.Graphics2D) graphics.create();
				g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
						java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
				Object fill = getClientProperty("fill");
				g.setColor(fill instanceof Color ? (Color) fill : SURFACE);
				g.fillRoundRect(0, 0, getWidth(), getHeight(), 8, 8);
				g.dispose();
			}

			@Override public java.awt.Dimension getMaximumSize()
			{
				return new java.awt.Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setBorder(javax.swing.BorderFactory.createEmptyBorder(10, 12, 10, 12));
		return panel;
	}
}

package com.zweetnekken.evidence;

import com.zweetnekken.model.ZweetnekkenModels;
import java.util.Map;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PvmDiaryTimeTest
{
	@Test
	void requiresStrictlyFasterTimeForTheSameActivity()
	{
		ZweetnekkenModels.PvmDiaryStatus status = new ZweetnekkenModels.PvmDiaryStatus();
		ZweetnekkenModels.PvmDiaryActivity solo = new ZweetnekkenModels.PvmDiaryActivity();
		solo.id = "cox-solo";
		solo.bestResult = new ZweetnekkenModels.PvmDiaryBestResult();
		solo.bestResult.value = 1_110_000L;
		status.activities.add(solo);

		assertTrue(PvmDiaryTime.improvesPublishedDiaryTime("cox-solo", 1_109_999L, status));
		assertFalse(PvmDiaryTime.improvesPublishedDiaryTime("cox-solo", 1_110_000L, status));
		assertFalse(PvmDiaryTime.improvesPublishedDiaryTime("cox-solo", 1_110_001L, status));
		assertTrue(PvmDiaryTime.improvesPublishedDiaryTime("cox-trios", 1_000_000L, status));
	}

	@Test
	void allowsFirstQualifyingTimeWithoutAPublishedBest()
	{
		assertTrue(PvmDiaryTime.improvesPublishedDiaryTime("cox-solo", 1_200_000L, null));
		assertTrue(PvmDiaryTime.improvesPublishedDiaryTime(
			"cox-solo", 1_200_000L, new ZweetnekkenModels.PvmDiaryStatus()));
	}

	@Test
	void comparesLocalEvidenceWithinTheSameAccountAndActivity()
	{
		ZweetnekkenModels.EventEnvelope run = new ZweetnekkenModels.EventEnvelope();
		run.player = new ZweetnekkenModels.PlayerIdentity();
		run.player.accountHash = "123";
		ZweetnekkenModels.EventEnvelope previous = new ZweetnekkenModels.EventEnvelope();
		previous.eventType = "diary";
		previous.player = new ZweetnekkenModels.PlayerIdentity();
		previous.player.accountHash = "123";
		previous.details.put("pvmDiary", Map.of("activityId", "cox-solo", "value", 1_110_000.0));

		assertTrue(PvmDiaryTime.hasFasterOrEqualDiaryTime(run, previous, "cox-solo", 1_110_000L));
		assertTrue(PvmDiaryTime.hasFasterOrEqualDiaryTime(run, previous, "cox-solo", 1_110_001L));
		assertFalse(PvmDiaryTime.hasFasterOrEqualDiaryTime(run, previous, "cox-solo", 1_109_999L));
		assertFalse(PvmDiaryTime.hasFasterOrEqualDiaryTime(run, previous, "cox-trios", 1_110_001L));
		previous.player.accountHash = "456";
		assertFalse(PvmDiaryTime.hasFasterOrEqualDiaryTime(run, previous, "cox-solo", 1_110_001L));
	}
}

package com.zweetnekken.pb;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class DiaryChatMessagesTest
{
	@Test
	void recognizesFormattedDoomCompletion()
	{
		String message = DiaryChatMessages.normalize(" @gre@Level\u00a010\tComplete! @red@");
		assertEquals(10L, DiaryChatMessages.doomLevel(message));
		assertNull(DiaryChatMessages.doomLevel("Level 10"));
		assertNull(DiaryChatMessages.doomLevel("Level 10 reached!"));
	}

	@Test
	void usesTheActualDeepDelveLevelFromCompletionChat()
	{
		assertEquals(10L, DiaryChatMessages.doomLevel(
			DiaryChatMessages.normalize("Delve level 8+ (10) duration: @red@1:56@red@, Personal best: 0:53")));
		assertEquals(8L, DiaryChatMessages.doomLevel("Delve level 8 duration: 1:56."));
		assertNull(DiaryChatMessages.doomLevel("You have failed Mokhaiotl Drift: The Doom finished the first burrow phase."));
		assertNull(DiaryChatMessages.doomLevel("Delve level 8+ (10)"));
	}

	@Test
	void leavesWaveSplitsOutOfSoloDurations()
	{
		assertNull(DiaryChatMessages.soloDuration("Wave 11 completed! Wave duration: 1:05.2"));
		assertNull(DiaryChatMessages.soloDuration("Wave 12 completed! Wave duration: 0:58. Personal best: 0:55."));
	}

	@Test
	void recognizesSoloKillCountsAndTheRunDuration()
	{
		assertEquals("Inferno", DiaryChatMessages.soloCompletionActivity("Your TzKal-Zuk kill count is: 2."));
		assertEquals("TzHaar Fight Cave", DiaryChatMessages.soloCompletionActivity("Your TzTok-Jad kill count is: 3."));
		assertEquals("Fortis Colosseum", DiaryChatMessages.soloCompletionActivity("Your Sol Heredit kill count is: 1."));
		assertEquals("Corrupted Gauntlet", DiaryChatMessages.soloCompletionActivity(
			"Your Corrupted Gauntlet completion count is: 14."));
		assertEquals("Vardorvis", DiaryChatMessages.soloCompletionActivity("Your Vardorvis kill count is: 32."));
		assertEquals("58:30", DiaryChatMessages.soloDuration("Fight duration: 58:30. Personal best: 52:00."));
		assertEquals("51:45", DiaryChatMessages.personalBestDuration("Duration: 51:45. (new personal best)"));
	}
}

package com.zweetnekken.pb;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class DiaryChatTemplateTest
{
	@Test
	void matchesConfiguredDoomCompletionAndNormalDelve()
	{
		DiaryChatTemplate completion = DiaryChatTemplate.compile("Level {wave} Complete!", true);
		DiaryChatTemplate delve = DiaryChatTemplate.compile("Delve level {wave} duration: {time}{rest}", true);
		assertEquals("12", completion.result("Level 12 Complete!"));
		assertEquals("7", delve.result("Delve level 7 duration: 1:56"));
		assertNull(completion.result("Level 12 entered!"));
		assertNull(delve.result("Delve level 8+ (10) duration: 1:56"));
	}

	@Test
	void readsDeepDelveFromConfiguredChatTemplate()
	{
		DiaryChatTemplate rule = DiaryChatTemplate.compile("Delve level 8+ ({wave}) duration: {time}{rest}", true);
		assertEquals("10", rule.result("Delve level 8+ (10) duration: 1:56, Personal best: 0:53"));
		assertEquals("11", rule.result("Delve level 8+ (11) duration: 1:59"));
		assertNull(rule.result("Delve level 8+ (10) entered"));
		assertNull(rule.result("Delve level 88 (10) duration: 1:56"));
	}

	@Test
	void keepsTheObservedTimeSeparateFromThePersonalBest()
	{
		DiaryChatTemplate rule = DiaryChatTemplate.compile("Colosseum duration: {time}{rest}", false);
		assertEquals("19:31.2", rule.result("Colosseum duration: 19:31.2. Personal best: 18:00"));
		assertNull(rule.result("Colosseum duration: 19:90"));
		assertNull(rule.result("Other activity duration: 19:31.2"));
		assertEquals("19:31.2", rule.result("Colosseum duration: 19:31.2. New personal best by 0:58."));
		assertNull(rule.result("You beat your previous personal best by 0:58."));
		assertNull(rule.result("Wave 12 completed! Wave duration: 0:58."));
	}

	@Test
	void rejectsUnboundedAndAmbiguousTemplateSyntax()
	{
		assertNull(DiaryChatTemplate.compile("{time}", false));
		assertNull(DiaryChatTemplate.compile("Arena duration: {rest}{time}", false));
		assertNull(DiaryChatTemplate.compile("Arena duration: {wave}", false));
		assertNull(DiaryChatTemplate.compile("Arena duration: {time} vs {time}", false));
	}
}

